-- ITH-108: preconfigured ITSM workflows by ticket type, priority and severity.
-- Published v1, DISABLED: an ITSM Admin enables the ones to use (Workflow Designer). Re-running skips names that already exist.
INSERT INTO itsm_workflows (ticket_type, name, description, match, rank, is_active, created_by, updated_by)
SELECT 'incident', 'Major incident (S1)', 'S1 severity (major incident): team and requester told at once, 15-minute pick-up, escalation when not picked up or not fixed in 2 hours, the resolution is signed off by an ITSM Admin before it is resolved.', '{"severity": ["S1"]}'::jsonb, 10, false, 'System (preconfigured)', 'System (preconfigured)'
WHERE NOT EXISTS (SELECT 1 FROM itsm_workflows WHERE ticket_type = 'incident' AND lower(name) = lower('Major incident (S1)'));
