SELECT w.id, 1, 'Published', '{"nodes": [{"id": "s", "type": "start", "label": "Raised", "x": 40, "y": 240, "config": {}}, {"id": "n1", "type": "notify", "label": "Alert team and requester", "x": 240, "y": 240, "config": {"to": ["team", "requester"], "title": "MAJOR incident {no}", "message": "{no}: {title} \u2014 major incident raised, the team is on it."}}, {"id": "o", "type": "stage", "label": "Open \u2014 15 min to pick up", "x": 460, "y": 240, "config": {"status": "Open", "timeoutHours": 0.25}}, {"id": "esc", "type": "stage", "label": "Escalated", "x": 680, "y": 420, "config": {"status": "Escalated"}}, {"id": "n2", "type": "notify", "label": "Tell team: escalated", "x": 460, "y": 420, "config": {"to": ["team", "assignee"], "title": "{no} escalated", "message": "{no}: {title} was not picked up / fixed in time and is escalated."}}, {"id": "w", "type": "stage", "label": "Working \u2014 2 h target", "x": 680, "y": 240, "config": {"status": "In Progress", "timeoutHours": 2}}, {"id": "h", "type": "stage", "label": "On hold", "x": 900, "y": 420, "config": {"status": "On Hold"}}, {"id": "ap", "type": "approval", "label": "Resolution sign-off (ITSM Admin)", "x": 900, "y": 240, "config": {"approverType": "itsm_admins", "title": "Sign off resolution of major incident {no}"}}, {"id": "rv", "type": "stage", "label": "Resolved", "x": 1120, "y": 240, "config": {"status": "Resolved"}}, {"id": "n3", "type": "notify", "label": "Tell requester: closed", "x": 1340, "y": 240, "config": {"to": ["requester", "team"], "title": "{no} closed", "message": "{no}: {title} is closed."}}, {"id": "end", "type": "end", "label": "Closed", "x": 1560, "y": 240, "config": {"status": "Closed"}}], "edges": [{"id": "s-n1-next", "from": "s", "to": "n1", "label": "", "outcome": "next"}, {"id": "n1-o-next", "from": "n1", "to": "o", "label": "", "outcome": "next"}, {"id": "o-w-next", "from": "o", "to": "w", "label": "Start work", "outcome": "next"}, {"id": "o-n2-timeout", "from": "o", "to": "n2", "label": "", "outcome": "timeout"}, {"id": "n2-esc-next", "from": "n2", "to": "esc", "label": "", "outcome": "next"}, {"id": "esc-w-next", "from": "esc", "to": "w", "label": "Start work", "outcome": "next"}, {"id": "w-n2-timeout", "from": "w", "to": "n2", "label": "", "outcome": "timeout"}, {"id": "w-h-next", "from": "w", "to": "h", "label": "Put on hold", "outcome": "next"}, {"id": "h-w-next", "from": "h", "to": "w", "label": "Resume", "outcome": "next"}, {"id": "w-ap-next", "from": "w", "to": "ap", "label": "Resolve (sign-off)", "outcome": "next"}, {"id": "ap-rv-approved", "from": "ap", "to": "rv", "label": "", "outcome": "approved"}, {"id": "ap-w-rejected", "from": "ap", "to": "w", "label": "", "outcome": "rejected"}, {"id": "rv-n3-next", "from": "rv", "to": "n3", "label": "Close", "outcome": "next"}, {"id": "n3-end-next", "from": "n3", "to": "end", "label": "", "outcome": "next"}]}'::jsonb, 'Preconfigured', 'System (preconfigured)', 'System (preconfigured)', 'System (preconfigured)', now()
FROM itsm_workflows w WHERE w.ticket_type = 'incident' AND lower(w.name) = lower('Major incident (S1)') AND NOT EXISTS (SELECT 1 FROM itsm_workflow_versions v WHERE v.workflow_id = w.id);
