INSERT INTO itsm_workflow_versions (workflow_id, version, status, definition, notes, created_by, updated_by, published_by, published_at)
SELECT w.id, 1, 'Published', '{"nodes": [{"id": "s", "type": "start", "label": "Raised", "x": 40, "y": 240, "config": {}}, {"id": "n", "type": "notify", "label": "Tell requester", "x": 240, "y": 240, "config": {"to": ["requester"], "title": "Emergency change {no}", "message": "{no}: {title} is waiting for emergency approval."}}, {"id": "d", "type": "stage", "label": "Draft", "x": 460, "y": 240, "config": {"status": "Draft"}}, {"id": "ea", "type": "approval", "label": "Emergency approval", "x": 680, "y": 240, "config": {"approverType": "itsm_admins", "title": "Emergency approval for {no}"}}, {"id": "rej", "type": "end", "label": "Rejected", "x": 900, "y": 420, "config": {"status": "Rejected"}}, {"id": "ip", "type": "stage", "label": "In progress", "x": 900, "y": 240, "config": {"status": "In Progress"}}, {"id": "ok", "type": "stage", "label": "Completed", "x": 1120, "y": 160, "config": {"status": "Completed"}}, {"id": "f", "type": "stage", "label": "Failed", "x": 1120, "y": 340, "config": {"status": "Failed"}}, {"id": "rb", "type": "stage", "label": "Rolled back", "x": 1340, "y": 340, "config": {"status": "Rolled Back"}}, {"id": "end", "type": "end", "label": "Closed", "x": 1560, "y": 240, "config": {"status": "Closed"}}], "edges": [{"id": "s-n-next", "from": "s", "to": "n", "label": "", "outcome": "next"}, {"id": "n-d-next", "from": "n", "to": "d", "label": "", "outcome": "next"}, {"id": "d-ea-next", "from": "d", "to": "ea", "label": "Submit", "outcome": "next"}, {"id": "ea-ip-approved", "from": "ea", "to": "ip", "label": "", "outcome": "approved"}, {"id": "ea-rej-rejected", "from": "ea", "to": "rej", "label": "", "outcome": "rejected"}, {"id": "ip-ok-next", "from": "ip", "to": "ok", "label": "Complete", "outcome": "next"}, {"id": "ip-f-next", "from": "ip", "to": "f", "label": "Failed", "outcome": "next"}, {"id": "f-rb-next", "from": "f", "to": "rb", "label": "Roll back", "outcome": "next"}, {"id": "ok-end-next", "from": "ok", "to": "end", "label": "Close", "outcome": "next"}, {"id": "rb-end-next", "from": "rb", "to": "end", "label": "Close", "outcome": "next"}]}'::jsonb, 'Preconfigured', 'System (preconfigured)', 'System (preconfigured)', 'System (preconfigured)', now()
FROM itsm_workflows w WHERE w.ticket_type = 'change' AND lower(w.name) = lower('Emergency change') AND NOT EXISTS (SELECT 1 FROM itsm_workflow_versions v WHERE v.workflow_id = w.id);
INSERT INTO audit_logs (entity_type, entity_id, action, performed_by, summary)
SELECT 'itsm_workflow', w.id, 'create', 'System (preconfigured)', 'Preconfigured workflow “' || w.name || '” added (published v1, disabled)'
FROM itsm_workflows w WHERE w.created_by = 'System (preconfigured)' AND NOT EXISTS (SELECT 1 FROM audit_logs a WHERE a.entity_type = 'itsm_workflow' AND a.entity_id = w.id AND a.action = 'create');
